def subarrays_with_k_distinct(nums, k):
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i, n):
            distinct = len(set(nums[i:j + 1]))                    # recomputes distinct values from scratch
            if distinct == k:
                count += 1
    return count


if __name__ == "__main__":
    print(subarrays_with_k_distinct([1, 2, 1, 2, 3], 2))

