import java.util.*;

public class Main {
    int subarraysWithKDistinct(int[] nums, int k) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                Set<Integer> distinct = new HashSet<>();
                for (int idx = i; idx <= j; idx++) distinct.add(nums[idx]);   // recomputes distinct values from scratch
                if (distinct.size() == k) count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.subarraysWithKDistinct(new int[]{1, 2, 1, 2, 3}, 2));
    }
}

