int subarraysWithKDistinct(vector<int>& nums, int k) {
    int n = (int)nums.size();
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            unordered_set<int> distinct;
            for (int idx = i; idx <= j; idx++) distinct.insert(nums[idx]);   // recomputes distinct values from scratch
            if ((int)distinct.size() == k) count++;
        }
    }
    return count;
}

