def subarrays_with_k_distinct(nums, k):
    def at_most(k):
        if k == 0:
            return 0
        counts = {}
        left = 0
        result = 0
        for right in range(len(nums)):
            counts[nums[right]] = counts.get(nums[right], 0) + 1
            while len(counts) > k:
                counts[nums[left]] -= 1
                if counts[nums[left]] == 0:
                    del counts[nums[left]]
                left += 1                                              # shrink until at most k distinct remain
            result += right - left + 1                                    # every subarray ending here, starting from left onward
        return result

    return at_most(k) - at_most(k - 1)                                # exactly k distinct values


