public class Main {
    int subarraysWithKDistinct(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);                       // exactly k distinct values
    }

    int atMost(int[] nums, int k) {
        if (k == 0) return 0;
        Map<Integer, Integer> counts = new HashMap<>();
        int left = 0, result = 0;
        for (int right = 0; right < nums.length; right++) {
            counts.merge(nums[right], 1, Integer::sum);
            while (counts.size() > k) {
                counts.merge(nums[left], -1, Integer::sum);
                if (counts.get(nums[left]) == 0) counts.remove(nums[left]);
                left++;                                                          // shrink until at most k distinct remain
            }
            result += right - left + 1;                                            // every subarray ending here, starting from left onward
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.subarraysWithKDistinct(new int[]{1, 2, 1, 2, 3}, 2));
    }
}

