#include <bits/stdc++.h>
using namespace std;

int atMost(vector<int>& nums, int k) {
    if (k == 0) return 0;
    unordered_map<int, int> counts;
    int left = 0, result = 0;
    for (int right = 0; right < (int)nums.size(); right++) {
        counts[nums[right]]++;
        while ((int)counts.size() > k) {
            counts[nums[left]]--;
            if (counts[nums[left]] == 0) counts.erase(nums[left]);
            left++;                                                            // shrink until at most k distinct remain
        }
        result += right - left + 1;                                              // every subarray ending here, starting from left onward
    }
    return result;
}

int subarraysWithKDistinct(vector<int>& nums, int k) {
    return atMost(nums, k) - atMost(nums, k - 1);                                 // exactly k distinct values
}

